	/*2. configurar el registro moder*/
	//PD12-15
	GPIOD->MODER &=~ (GPIO_MODER_MODE12 | GPIO_MODER_MODE13 | GPIO_MODER_MODE14 |
			GPIO_MODER_MODE15);

//	GPIOD->MODER &=~ (0x7F)<<GPIO_MODER_MODE12_Pos;//0b1111 1111
