	GPIOD->BSRR |= GPIO_BSRR_BS12; //or
	GPIOD->BSRR |= GPIO_BSRR_BR12;

	*((volatile uint32_t *)0x20000300) |= 1<<2;
	*((volatile uint32_t *)0x20000300) &=~ 1<<2;

	*((volatile uint32_t *)0x22006008) = 1;
	*((volatile uint32_t *)0x22006008) = 0;
	//0x22000000U->SRAM
	//0x42000000U->PERIFERICOS
	LED1 = 1;
	LED1 = 0;

